import{_ as t,o,c as d,a2 as a}from"./chunks/framework.DHtetOlu.js";const m=JSON.parse('{"title":"Console","description":"","frontmatter":{},"headers":[],"relativePath":"en/scripting/console.md","filePath":"en/scripting/console.md"}'),r={name:"en/scripting/console.md"};function s(n,e,c,i,l,u){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h1><p>Everything you do in the interface shows up in the <strong>console</strong> (below the canvas) as the equivalent command. The reverse also holds: typing a command performs the action, and the drawing follows. It is the same language used by <a href="./bridge.html">local bridge</a> scripts and by the exported script.</p><h2 id="the-language" tabindex="-1">The language <a class="header-anchor" href="#the-language" aria-label="Permalink to &quot;The language&quot;">​</a></h2><p>A Python-like language:</p><ul><li>numbers, strings (<code>&quot;...&quot;</code> or <code>&#39;...&#39;</code>), tuples <code>(x, y)</code>, lists <code>[a, b]</code>, <code>True</code>, <code>False</code> and <code>None</code>;</li><li>keyword arguments: <code>g.circle((0, 0), r=5)</code>;</li><li>console variables: <code>a = g.point((0, 0))</code> stores the id of the new point for later use;</li><li>comments with <code>#</code>.</li></ul><p>Lengths are numbers in the project unit or strings with a unit (<code>&quot;5 mm&quot;</code>, <code>&quot;0.2 in&quot;</code>). Point coordinates, such as <code>(x, y)</code>, are in mm. Angles are strings with a unit (<code>&quot;30 deg&quot;</code>).</p><h2 id="objects" tabindex="-1">Objects <a class="header-anchor" href="#objects" aria-label="Permalink to &quot;Objects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Stage</th><th>Examples</th></tr></thead><tbody><tr><td><code>g</code></td><td>Geometry</td><td><code>g.line((0, 0), (40, 0))</code>, <code>g.distance(&quot;l1&quot;, &quot;40 mm&quot;)</code>, <code>g.var(&quot;g&quot;, &quot;0.5 mm&quot;)</code></td></tr><tr><td><code>m</code></td><td>Mesh</td><td><code>m.region((5, 5), material=&quot;mat_cu&quot;)</code>, <code>m.circuit(&quot;Coil&quot;, current=&quot;10&quot;)</code>, <code>m.generate()</code></td></tr><tr><td><code>s</code></td><td>Solver</td><td><code>s.physics(&quot;n2&quot;, analysis=&quot;transient&quot;, dt=&quot;0.001&quot;, t_end=&quot;0.05&quot;)</code>, <code>s.solve()</code></td></tr><tr><td><code>r</code></td><td>Results</td><td><code>r.view(&quot;n2&quot;)</code>, <code>r.table(&quot;n2&quot;)</code>, <code>r.result(&quot;Coil_L&quot;)</code></td></tr><tr><td><code>c</code></td><td>Schematic</td><td><code>c.part(&quot;n5&quot;, &quot;R&quot;, value=&quot;0.5&quot;)</code>, <code>c.wire(...)</code></td></tr></tbody></table><p>Without an object, a command counts as geometry: <code>line((0, 0), (10, 0))</code> is the same as <code>g.line(...)</code>.</p><h2 id="global-functions" tabindex="-1">Global functions <a class="header-anchor" href="#global-functions" aria-label="Permalink to &quot;Global functions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Does</th></tr></thead><tbody><tr><td><code>help()</code></td><td>lists the commands</td></tr><tr><td><code>getid(&quot;name&quot;)</code></td><td>id of an entity, region or node by name</td></tr><tr><td><code>undo()</code>, <code>redo()</code></td><td>undo and redo</td></tr><tr><td><code>fit()</code></td><td>fits the view</td></tr><tr><td><code>reset()</code></td><td>starts an empty project with the default libraries (for scripts; the open file does not change)</td></tr></tbody></table><h2 id="console-features" tabindex="-1">Console features <a class="header-anchor" href="#console-features" aria-label="Permalink to &quot;Console features&quot;">​</a></h2><ul><li><strong>Tab</strong> completes commands, ids, names and variables; inside quotes it suggests ids and names from the drawing.</li><li><strong>↑</strong> and <strong>↓</strong> browse the history.</li><li>The copy button copies the history as a script; undone items are shown in gray.</li><li>Errors show a readable message without changing the model.</li></ul><h2 id="exported-script" tabindex="-1">Exported script <a class="header-anchor" href="#exported-script" aria-label="Permalink to &quot;Exported script&quot;">​</a></h2><p>The <code>&lt;/&gt;</code> button next to <strong>Model</strong> writes a script that starts with <code>clear()</code> and rebuilds the whole project with the same ids: entities, constraints, groups, variables, materials, regions, boundaries, mesh, physics and results. An automated test guarantees the round trip (the rebuilt model is identical). You can paste the script into the console or send it from an external script, for example to sweep parameters.</p><p>See the <a href="./api.html">full API reference</a>.</p>',16)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
